import React from 'react';

function Summary({ answers, questions, onRestart }) {
  const calculateTotalCost = () => {
    return Object.entries(answers).reduce((total, [questionIndex, answer]) => {
      return total + (answer.cost || 0);
    }, 0);
  };

  const calculateStyle = () => {
    const styleWeights = {
      traditional: 0,
      modern: 0,
      minimal: 0,
      nature: 0,
      luxury: 0,
    };

    Object.entries(answers).forEach(([questionIndex, answer]) => {
      if (answer.tags) {
        answer.tags.forEach(tag => {
          if (styleWeights[tag] !== undefined) {
            styleWeights[tag]++;
          }
        });
      }
    });

    return Object.entries(styleWeights).reduce((a, b) => 
      a[1] > b[1] ? a : b
    )[0];
  };

  const getStyleDescription = (style) => {
    const descriptions = {
      traditional: "งานศพแบบไทยดั้งเดิม: บรรยากาศแบบวัดไทย มีพระสวด ดอกไม้ประดับ บายศรี",
      modern: "งานศพร่วมสมัยและเรียบง่าย: ไม่มีพระ ไม่เน้นพิธี มีเพียงคำพูดจากคนใกล้ชิด",
      minimal: "งานศพเรียบง่าย: เน้นความสงบและความหมาย",
      nature: "งานศพในธรรมชาติ: ริมแม่น้ำหรือในป่า บรรยากาศเงียบสงบ ใช้โลงไม้หรือเผาแบบเรียบง่าย",
      luxury: "งานศพหรูหรา: ในห้องประชุมโรงแรมหรือสถานที่หรู ดอกไม้เต็มงาน มีอาหารบริการระดับสูง"
    };
    return descriptions[style] || descriptions.modern;
  };

  const totalCost = calculateTotalCost();
  const style = calculateStyle();
  const breakevenGuests = Math.ceil(totalCost / 1000);

  return (
    <div className="bg-white shadow rounded-lg p-6">
      <h2 className="text-2xl font-bold text-gray-900 mb-6">
        ผลการวางแผนงานศพของคุณ
      </h2>

      <div className="space-y-6">
        <div className="border-b pb-4">
          <h3 className="text-lg font-semibold text-gray-900 mb-2">รูปแบบงานศพ</h3>
          <p className="text-gray-700">{getStyleDescription(style)}</p>
        </div>

        <div className="border-b pb-4">
          <h3 className="text-lg font-semibold text-gray-900 mb-2">ประมาณการค่าใช้จ่าย</h3>
          <p className="text-gray-700">
            งบประมาณทั้งหมด: {totalCost.toLocaleString()} บาท
          </p>
          <p className="text-gray-700">
            จำนวนแขกที่ควรเชิญเพื่อคุ้มค่า: {breakevenGuests} คน
            (คิดจากค่าใช้จ่ายเฉลี่ย 1,000 บาทต่อคน)
          </p>
        </div>

        <div className="border-b pb-4">
          <h3 className="text-lg font-semibold text-gray-900 mb-2">ข้อความจากใจ</h3>
          <p className="text-gray-700">
            ขอบคุณที่วางแผนวันสุดท้ายของชีวิตอย่างตั้งใจ
          </p>
        </div>

        <button
          onClick={onRestart}
          className="w-full bg-primary text-white py-3 px-4 rounded-lg hover:bg-primary-dark transition-colors duration-200"
        >
          เริ่มใหม่อีกครั้ง
        </button>
      </div>
    </div>
  );
}

export default Summary;
